monitor BoundedBuffer {
    queue buffer;
    int count = 0, capacity = N;
    condition notFull, notEmpty;

    procedure deposit(item) {
        while (count == capacity) wait(notFull);
        buffer.add(item);
        count = count + 1;
        signal(notEmpty);
    }

    procedure remove() {
        while (count == 0) wait(notEmpty);
        item = buffer.take();
        count = count-1;
        signal(notFull);
        return item;
    }
}

